questionvariables.text:
/*define coefficients of the two lines for the worked solution*/
aa:rand(3)+1;
bb:rand(3)+1;
cc_1:(rand(3)+1);
cc_2:rand_with_prohib(1,3,[cc_1]); /*should not be the same line*/

eq1: aa*x+bb*y=bb*cc_1;  /*want integer intercept*/
eq2: aa*x+bb*y=bb*cc_2;
line1: expand(-aa/bb*x+cc_1);
line2: expand(-aa/bb*x+cc_2);

feedbackvariables.text:
corr_form_1:if (lhs(ans1) - coeff(lhs(ans1),x)*x - coeff(lhs(ans1),y)*y =0 and ({hipow(lhs(ans1),x),hipow(lhs(ans1),y)}={1} and {hipow(rhs(ans1),x),hipow(rhs(ans1),y)}={0}))  then 1 else 0;
corr_form_2:if (lhs(ans2) - coeff(lhs(ans2),x)*x - coeff(lhs(ans2),y)*y =0 and ({hipow(lhs(ans2),x),hipow(lhs(ans2),y)}={1} and {hipow(rhs(ans2),x),hipow(rhs(ans2),y)}={0}))  then 1 else 0;


plot_form_ans1:expand(solve(ans1,y)[1])
plot_form_ans2:expand(solve(ans2,y)[1])

plot_ans1:rhs(plot_form_ans1);
plot_ans2:rhs(plot_form_ans2);

grad_1:coeff(plot_ans1,x);
grad_2:coeff(plot_ans2,x);

xmin:if solve([ans1,ans2],[x,y])=[] then -4 elseif rhs(solve([ans1,ans2],[x,y])[1][1])<=-4 then rhs(solve([ans1,ans2],[x,y])[1][1])-1 else -4;
xmax:if solve([ans1,ans2],[x,y])=[] then 4 elseif rhs(solve([ans1,ans2],[x,y])[1][1])>=4 then rhs(solve([ans1,ans2],[x,y])[1][1])+1 else 4;

ymin:if solve([ans1,ans2],[x,y])=[] then -2 elseif rhs(solve([ans1,ans2],[x,y])[1][2])<=-2 then rhs(solve([ans1,ans2],[x,y])[1][2])-1 else -2;
ymax:if solve([ans1,ans2],[x,y])=[] then 5 elseif rhs(solve([ans1,ans2],[x,y])[1][2])>=5 then rhs(solve([ans1,ans2],[x,y])[1][2])+1 else 5;
